<template>
  <div class="page-container gpm-page"><div class="page-head"><div><h2>计划管理统计</h2><p>汇总主体、地块、作物结构与年度落实趋势。</p></div><div class="region-filter"><el-select v-model="regionCode" placeholder="选择统计区域" clearable style="width:180px" @change="load"><el-option label="全省" value="340000"/><el-option label="阜阳市" value="341200"/><el-option label="太和县" value="341222"/><el-option label="涡阳县" value="341622"/><el-option label="肥西县" value="340123"/></el-select><el-button type="primary" @click="load">刷新统计</el-button></div></div><div class="stat-grid"><div class="stat-card"><span>登记主体</span><strong>{{ data.overview.totalSubjects }}</strong><small>个</small></div><div class="stat-card"><span>关联地块</span><strong>{{ data.overview.totalPlots }}</strong><small>块</small></div><div class="stat-card"><span>经营面积</span><strong>{{ data.overview.totalArea }}</strong><small>亩</small></div><div class="stat-card"><span>最新落实率</span><strong>{{ latestRate }}%</strong><small>按月度趋势</small></div></div><div class="content-grid"><div class="panel"><div class="panel-title"><span class="title-text">作物面积结构</span></div><el-table :data="data.crops" stripe><el-table-column prop="name" label="作物"/><el-table-column prop="value" label="计划面积(万亩)"/><el-table-column label="占比"><template #default="{row}">{{ totalCrop ? (row.value / totalCrop * 100).toFixed(1) : 0 }}%</template></el-table-column></el-table></div><div class="panel"><div class="panel-title"><span class="title-text">月度落实趋势</span></div><el-table :data="data.trend" stripe><el-table-column prop="month" label="月份"/><el-table-column prop="planArea" label="计划面积"/><el-table-column prop="implementRate" label="落实率"><template #default="{row}"><el-progress :percentage="row.implementRate"/></template></el-table-column><el-table-column prop="sowRate" label="播种率"/></el-table></div></div></div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { fetchPlanStats } from '@/api/gpm'
import { useUserStore } from '@/stores/user'
const userStore = useUserStore(); const regionCode = ref(userStore.role?.regionCode || '340000'); const data = ref({ overview: { totalSubjects: 0, totalPlots: 0, totalArea: 0 }, crops: [], trend: [] }); const totalCrop = computed(() => data.value.crops.reduce((sum, item) => sum + item.value, 0)); const latestRate = computed(() => data.value.trend[data.value.trend.length - 1]?.implementRate || 0); const load = async () => { data.value = await fetchPlanStats(userStore.role, regionCode.value) }; onMounted(load)
</script>
<style lang="scss" scoped>.gpm-page{gap:12px;overflow:auto}.page-head{display:flex;justify-content:space-between}.region-filter{display:flex;gap:8px;align-items:center}.eyebrow{color:var(--ah-primary);font-size:11px;letter-spacing:1px;font-weight:700}h2{margin:4px 0;color:var(--ah-text);font-size:22px}.page-head p{color:var(--ah-text-secondary);font-size:13px}.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat-card{background:#fff;padding:16px;border-radius:8px;border-left:4px solid var(--ah-primary);box-shadow:0 1px 4px rgba(15,62,120,.06)}.stat-card span,.stat-card small{display:block;color:var(--ah-text-secondary);font-size:12px}.stat-card strong{display:block;font-size:26px;margin:8px 0;color:var(--ah-text)}.content-grid{display:grid;grid-template-columns:1fr 1.4fr;gap:12px}@media(max-width:900px){.stat-grid,.content-grid{grid-template-columns:1fr 1fr}.content-grid{grid-template-columns:1fr}} </style>
